import numpy as np
lines = open('answer.xyz').read().strip().split('\n')
n = int(lines[0])
els, P = [], []
for l in lines[2:2+n]:
    s = l.split()
    els.append(s[0]); P.append([float(s[1]),float(s[2]),float(s[3])])
P = np.array(P)
def d(i,j): return np.linalg.norm(P[i]-P[j])
def show(i,j,label):
    print(f"{label:12s} {els[i]}{i}-{els[j]}{j}: {d(i,j):.3f} A")
# V is atom 0
print("--- V coordination sphere ---")
for i in range(n):
    if i!=0 and d(0,i) < 2.6:
        print(f"V-{els[i]}{i}: {d(0,i):.3f}")
print("--- chelate A bonds ---")
# find O and N indices
O = [i for i,e in enumerate(els) if e=='O']
N = [i for i,e in enumerate(els) if e=='N']
print("O idx:",O, "N idx:",N)
for i in O:
    for j in range(n):
        if els[j]=='C' and d(i,j)<1.7: print(f"O{i}-C{j}: {d(i,j):.3f}")
for i in N:
    for j in range(n):
        if els[j]=='C' and d(i,j)<1.7: print(f"N{i}-C{j}: {d(i,j):.3f}")
        if els[j]=='H' and d(i,j)<1.3: print(f"N{i}-H{j}: {d(i,j):.3f}")
# backbone C-C bonds
print("--- short C-C (backbone/methyl/ring) ---")
C = [i for i,e in enumerate(els) if e=='C']
for a in range(len(C)):
    for b in range(a+1,len(C)):
        i,j = C[a],C[b]
        if d(i,j)<1.6: print(f"C{i}-C{j}: {d(i,j):.3f}")
EOF
